"""Render the measured A/B report as one standalone, credential-free HTML file."""
import json
import sys
from collections import defaultdict, deque
from pathlib import Path

source = Path(sys.argv[1] if len(sys.argv) > 1 else '.data/benchmarks/roundtrip-ab.json')
target = Path(sys.argv[2])
report = json.loads(source.read_text())
labels = {
 'warm.thread_start': ('Fresh conversation setup', 'Creates a fresh conversation and request-specific MCP configuration in the retained process. Overlaps MCP initialization.'),
 'warm.thread_delete': ('Release conversation', 'Deletes this completed conversation and releases its MCP processes; keeps the shared runtime alive.'),
 'discord.typing': ('Typing acknowledgement', 'Runs in the background in B. Only the initial POST blocks preparation in A; refreshes are background work in both.'),
 'discord.nearby_history': ('Nearby-history GET', 'Real Discord request. Replay discards messages newer than the original input, keeping the same empty context.'),
 'host.guild_memory': ('Load server memory', 'Reads the copied production memory snapshot.'),
 'host.reaction_discovery': ('Discover reaction capabilities', 'Cold cache: four parallel Discord reads. Warm cache: in-memory lookup.'),
 'discord.channel_permissions': ('Channel permissions GET', 'Parallel child of reaction discovery.'),
 'discord.bot_permissions': ('Bot member GET', 'Parallel child of reaction discovery.'),
 'discord.guild_roles': ('Guild roles GET', 'Parallel child of reaction discovery.'),
 'discord.guild_emojis': ('Guild emojis GET', 'Parallel child of reaction discovery.'),
 'host.jev': ('Jev route + repository', 'One real TypeSafe HTTP request: request construction, transport, typed judgments, body parsing and validation. Internal network/inference split is unavailable.'),
 'worker.attachments_workspace': ('Prepare workspace / attachments', 'Creates the temporary request workspace. This request has no attachments.'),
 'worker.prompt_config': ('Compile prompt / configuration', 'Builds the same production prompt and CLI configuration. Includes the nested prompt-telemetry write.'),
 'worker.trace_write_start': ('Persist job start', 'Real SQLite write to an isolated benchmark trace database.'),
 'worker.trace_write_prompt': ('Persist prompt metadata', 'Real SQLite update; nested within prompt/config compilation.'),
 'worker.trace_write_finish': ('Persist job result', 'Real SQLite update after worker cleanup.'),
 'worker.trace_sql': ('Previous-trace SQL read', 'Real trace-store query; no previous answer exists for the replayed empty-channel state.'),
 'codex.parse_output': ('Parse Codex output', 'Parses the completed structured response.'),
 'worker.validate_identity': ('Validate answer identity', 'Checks the first-person reply; includes repair if one were needed.'),
 'worker.outgoing_artifacts': ('Prepare outgoing artifacts', 'Validates the outgoing response and scans generated artifacts.'),
 'worker.cleanup': ('Clean temporary workspace', 'Completes before the worker result is returned.'),
 'host.answer_validation': ('Validate host response', 'Parses the answer decision and applies a reaction if selected.'),
 'discord.latest_message': ('Latest-message GET', 'A waits for this to choose normal post versus explicit reply. B reads cached state and skips this GET.'),
 'discord.post_reply': ('Reply POST → acknowledgement', 'Real Discord send, including the HTTP response body. This is the benchmark endpoint; client rendering is excluded.'),
 'mcp.initialize': ('MiniSago MCP initialize', 'Host-side HTTP handler duration only; overlaps Codex session startup.'),
 'mcp.notifications/initialized': ('MCP initialized notification', 'Host-side HTTP handler duration only; overlaps session startup.'),
 'mcp.tools/list': ('MiniSago MCP tool discovery', 'Host-side HTTP handler duration only. Public campus MCP and media stdio startup are not individually exposed.'),
}
def sanitize(report):
    clean = {'date': report['collectedAt'][:10], 'runs': []}
    for run in report['runs']:
        assert not run.get('failed') and run.get('replyId') and not run.get('fallback')
        assert run['contextCounts']['answer'] == 0
        assert run['profiles']['answer'] == {'model':'gpt-5.6-luna','reasoningEffort':'high'}
        origin = run['startedAt']
        events = [e for e in report['events'] if e['run'] == run['id']]
        pending = defaultdict(deque)
        spans = []
        marks = defaultdict(list)
        for e in events:
            key = (e['scope'], e['name'])
            at = e['at'] - origin
            if e['phase'] == 'start': pending[key].append(at)
            elif e['phase'] == 'end':
                start = pending[key].popleft()
                assert at >= start and not e.get('failed')
                spans.append({'scope':e['scope'], 'name':e['name'], 'start':start, 'end':at})
            else: marks[key].append(at)
        assert not any(pending.values())
        def span(name, scope='host'):
            return next(s for s in spans if s['scope'] == scope and s['name'] == name)
        routing, answer = span('host.routing'), span('host.answer_dispatch')
        boundaries = [0, routing['start'], routing['end'], answer['start'], answer['end'], run['elapsedMs']]
        assert all(b >= a for a,b in zip(boundaries,boundaries[1:]))
        stage_names = ['Prepare', 'Route', 'Trace + handoff', 'Answer', 'Deliver']
        stages = [{'name':n, 'start':a, 'end':b} for n,a,b in zip(stage_names,boundaries,boundaries[1:])]
        detail = []
        for s in spans:
            scope, name = s['scope'], s['name']
            if name not in labels and scope != 'http': continue
            if scope == 'route': stage = 1
            elif scope in ('answer','mcp'): stage = 3
            elif scope == 'trace': stage = 2
            elif name == 'host.jev': stage = 1
            elif name in ('host.answer_validation','discord.latest_message','discord.post_reply') or (scope == 'http' and any(x in name for x in ('latest_message','post_reply'))): stage = 4
            else: stage = 0
            if name.startswith('discord.typing') and s['start'] > 100: stage = 5
            if scope == 'http':
                request_name = name.split('.http.')[0]
                title = labels.get(request_name,(request_name,''))[0]
                suffix = name.split('.http.')[1]
                label = title + ' · ' + {'response_headers':'wait for HTTP headers','decode_body':'decode body','rate_limit_wait':'rate-limit backoff'}.get(suffix,suffix)
                note = 'Nested inside the corresponding request. Header wait combines DNS/TLS if needed, network transit, and Discord service time; those parts are not separately exposed.'
            else: label,note = labels[name]
            detail.append({**s, 'label':label, 'note':note, 'stage':stage, 'nested':scope in ('http','mcp') or name in ('worker.trace_write_prompt','discord.channel_permissions','discord.bot_permissions','discord.guild_roles','discord.guild_emojis')})
        for scope,stage in [('route',1),('answer',3),('trace',2)]:
            def mark(name, last=False):
                vals = marks.get((scope,name),[])
                return (vals[-1] if last else vals[0]) if vals else None
            pairs = [
              ('bridge.sent','bridge.worker_received','WebSocket dispatch','Actual loopback WebSocket bytes, not the deployed cross-container transport.'),
              ('codex.spawn','codex.thread.started','Process + session startup','Observed process spawn to thread-start event. Includes startup/auth/config/MCP connection work. Only the local MiniSago MCP HTTP handlers have additional individual spans.'),
              ('codex.thread.started','codex.turn.started','Turn setup','Observed thread-start to turn-start events; internal work is not separately exposed.'),
              ('codex.turn.started','codex.item.completed.agent_message','Model turn / service wait','Cold: turn-start notification to completed answer. Warm: turn/start RPC submission to completed answer, including RPC setup. Combines service queue/network/model work; not pure inference.'),
              ('codex.item.completed.agent_message','codex.turn.completed','Finalize turn','Completed answer to turn-completed event.'),
              ('codex.turn.completed','codex.exited','Process exit / output drain','Wait for stdout/stderr closure and process exit after turn completion.'),
              ('bridge.worker_result_sent','bridge.result_received','WebSocket return','Actual loopback result transport and host dispatch resolution.'),
            ]
            for start,end,label,note in pairs:
                a,b=mark(start),mark(end,True)
                if a is not None and b is not None:
                    assert b >= a
                    detail.append({'scope':scope,'name':label,'label':label,'note':note,'start':a,'end':b,'stage':stage,'nested':False})
        detail.sort(key=lambda s:(s['stage'],s['start'],s['end']))
        clean['runs'].append({
          'id':run['id'], 'variant':run['variant'], 'pair':run['pair'], 'mode':run['mode'],
          'total':run['elapsedMs'], 'stages':stages, 'detail':detail,
          'reply':run['answer']['reply'], 'jev':run.get('jev'),
          'rateLimits':sum('http.status.429' in e['name'] for e in events),
          'prompts': {k:{'developer':v.get('developerCharacters'), 'context':v.get('contextCharacters')} for k,v in run['prompts'].items()},
        })
    idle = report.get('idle')
    if idle:
        clean['idle'] = {'cpuPercent': idle['cpuPercentOfOneCore'], 'rssMiB': idle['end']['rssBytes']/1048576, 'processes': len(idle['end']['processes']), 'durationMs': idle['durationMs']}
    return clean

clean = {'original': sanitize(report)}
if len(sys.argv) > 3:
    clean['warm'] = sanitize(json.loads(Path(sys.argv[3]).read_text()))

